/bin/zsh -lc "node - <<'NODE'
const fs = require('node:fs');
const crypto = require('node:crypto');
const files = ['yss-project.yaml', 'plan.md', 'review.json', 'state.json', 'entry-result.json', 'reconciliation.json', 'CONTEXT.md', '.template-spec/process/lifecycle-registry.yaml', 'docs/.scratch/demo/spec.md', 'docs/.scratch/demo/parent-ticket.md', ...fs.readdirSync('approval').map(name => 'approval/' + name)];
const hashes = Object.fromEntries(files.map(file => [file, 'sha256:' + crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex')]));
const review = JSON.parse(fs.readFileSync('review.json', 'utf8'));
const comparisons = review.basis.map(({ref,digest}) => ({ref, expected:digest, actual:hashes[ref], matches:digest === hashes[ref]}));
console.log(JSON.stringify({hashes, comparisons}, null, 2));
NODE"

