for (const [file, digest] of Object.entries(expected)) {
  const actual = 'sha256:' + crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
  assert.equal(actual, digest, '原资产发生变化: ' + file);
}
console.log('resume-result.json JSON 与必需字段校验通过；' + Object.keys(expected).length + ' 个原资产的 SHA-256 保持一致。');

NODE"

